#include "bounded_frame_writer_candidate.h"
#include <iostream>
int main(){try{auto root=std::filesystem::path("work/frame-writer-test-v1");std::filesystem::create_directories(root);{BoundedFrameWriterCandidate writer;for(unsigned n=0;n<32;++n)writer.submit(root/(std::to_string(n)+".bin"),std::vector<uint8_t>(4096,uint8_t(n)));writer.flush();}for(unsigned n=0;n<32;++n){std::ifstream file(root/(std::to_string(n)+".bin"),std::ios::binary);std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});if(bytes!=std::vector<uint8_t>(4096,uint8_t(n)))throw std::runtime_error("writer bytes");}size_t failures=0;{BoundedFrameWriterCandidate writer;writer.submit(root,{1,2,3});try{writer.flush();}catch(const std::runtime_error&){++failures;}try{writer.submit(root/"after-failure.bin",{4});}catch(const std::runtime_error&){++failures;}}if(failures!=2)throw std::runtime_error("writer failure lost");{BoundedFrameWriterCandidate writer;writer.submit(root/"destructor-flush.bin",{7,8,9});}std::ifstream file(root/"destructor-flush.bin",std::ios::binary);std::vector<uint8_t>bytes((std::istreambuf_iterator<char>(file)),{});if(bytes!=std::vector<uint8_t>({7,8,9}))throw std::runtime_error("destructor flush");std::cout<<"bounded frame writer passed frames=32 failures=2 destructor_flush=verified pending_bound=1\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
